'use strict';
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const day=(n)=>{const d=new Date(2026,10,30+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const today=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const fmt=d=>new Date(d+'T12:00:00').toLocaleDateString('fr-FR',{weekday:'short',day:'numeric',month:'short'});
const ef=n=>`Endurance facile ${n} min, RPE 2–4, conversation aisée. Marche si nécessaire. Inclure 5 min très faciles au début et à la fin.`;
const reprise='5 min marche, 5 × (2 min trot + 1 min marche), 5 min marche. RPE 2–3.';
const raw=[
['Reprise','Vélo facile',35,'25 min marche/course',25,0,'Reprise 25 min',25,reprise],
['Reprise','Marche/course',30,'Marche/course',30,0,'Sortie progressive',35,'5 min marche, 4 × (3 min trot + 2 min marche), 5 min marche. Dimanche 5 répétitions si récupération complète.'],
['Base aérobie','Test EF',30,'EF',30,0,'SL facile',40,'5 min faciles + 20 min à effort facile régulier + 5 min retour au calme.'],
['Base aérobie','Accélérations',35,'EF',35,0,'SL facile',50,'20 min EF + 4 × (15 s accélération relâchée + 75 s trot) + 9 min EF.'],
['Base aérobie','5 km contrôlé',0,'EF',35,0,'SL facile',60,'10 min faciles + 5 km RPE 4–5 + 5 min faciles. Remplacer par 20–30 min si nécessaire.'],
['Développement','6 × 1 min',45,'EF',35,20,'SL facile',60,'15 min EF + 6 × (1 min rapide RPE 7–8 + 1 min 30 trot) + 15 min EF.'],
['Assimilation','Test EF',35,'EF',30,0,'SL facile',50,'10 min EF + 20 min à allure facile de référence + 5 min EF.'],
['Développement','VO₂ max 5 × 2 min',45,'EF',40,25,'SL facile',70,'15 min EF + 5 × 2 min RPE 8, 2 min trot entre blocs + 12 min EF.'],
['Développement','5 km chronométré',0,'EF',35,0,'SL facile',75,'15 min EF + 3 × (15 s accélération + 45 s trot) + 5 km chrono régulier + 10 min EF.'],
['Seuil','3 × 6 min',49,'EF',40,25,'SL facile',80,'15 min EF + 3 × 6 min RPE 7–8, 3 min trot entre blocs + 10 min EF.'],
['Assimilation','5 km contrôlé',0,'EF',35,0,'SL facile',70,'10 min EF + 5 km au même protocole que S5 + 5 min EF.'],
['Test 10 km','EF',40,'EF + accélérations',31,0,'10 km chronométré',0,ef(40)],
['Spécifique','EF',30,'3 × 10 min AS21',61,25,'SL facile',100,ef(30)],
['Spécifique','EF',40,'EF',40,25,'SL spécifique',110,ef(40)],
['Affûtage','2 × 8 min AS21',44,'EF',30,0,'SL facile',65,'15 min EF + 2 × 8 min AS21, 3 min trot entre blocs + 10 min EF.'],
['Compétition','3 × 2 min AS21',25,'EF',20,0,'Semi-marathon',0,'10 min EF + 3 × 2 min AS21, 1 min trot entre blocs + 7 min EF.']];
function defaults(){return raw.map((r,i)=>{let s=[];const add=(d,sport,title,minutes,detail,optional=false)=>s.push({id:`w${i+1}-${d}-${sport.normalize("NFD").replace(/\p{Diacritic}/gu,"")}${i===0&&title==="Renforcement jambes"?"-legs":""}`,date:day(i*7+d),sport,title,minutes,detail,optional});add(0,'Musculation',i>13?'Push léger':'Push',45,'Haut du corps, RIR 2–3.',i>14);if(i<15){add(2,'Musculation',i===14?'Pull léger':'Pull',45,'Haut du corps, RIR 2–3.');add(4,'Musculation',i===14?'Upper léger':'Upper',45,'Haut du corps, RIR 2–3.',i>13);}if(i===0){add(1,'Vélo',r[1],35,'5 min 50–65 W, 25 min 80–85 W, 5 min 40–60 W. RPE 2–3.');add(4,'Course',r[3],25,reprise)}else{add(1,'Course',r[1],r[2],r[8]);add(3,'Course',r[3],r[4],i===12?'15 min EF + 3 × 10 min AS21, 3 min trot entre blocs + 10 min EF.':i===11?'25 min EF + 4 × (15 s accélération + 75 s trot).':i===1?r[8]:ef(r[4]));}if(r[5])add(4,'Course','EF bonus',r[5],ef(r[5]),true);if(i<14&&![8,11].includes(i))add(i===0?2:1,'Musculation','Renforcement jambes',30,'2 × 6–8 presse, 2 × 8–10 SDT roumain, 2 × 8 fentes/jambe, 2 × 12–15 mollets. RIR 3. Supprimer si fatigue.',true);add(6,'Course',r[6],r[7],i===0?reprise:i===1?'5 min marche + 5 × (3 min trot + 2 min marche) + 5 min marche.':i===11?'15 min EF + 3 accélérations progressives + 10 km chrono + 10 min EF. Seulement si prêt.':i===13?'35 min EF + 2 × 3 km AS21 validée, 5 min trot entre blocs + EF jusqu’à 100–110 min. Seulement si sorties précédentes bien tolérées.':i===15?'21,0975 km. Allure à valider après tests; cible 4:58/km.':ef(r[7]));return {week:i+1,phase:r[0],sessions:s.sort((a,b)=>a.date.localeCompare(b.date))}})}
const KEY='hybrid-run-v1';let state;try{state=JSON.parse(localStorage.getItem(KEY))}catch{}if(!state||!Array.isArray(state.plan)||!Array.isArray(state.logs))state={plan:defaults(),logs:[],medical:false,settings:{target:'1:45',pace:'4:58',ef:'À définir',threshold:'À définir',vma:'À définir'},version:'V4'};
let tab='home', week=Math.max(0,Math.min(16,Math.floor((new Date(today()+'T12:00:00')-new Date(day(0)+'T12:00:00'))/604800000)+1)), editing=null, planned=null;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch(e){alert('Sauvegarde locale impossible. Exporte tes données avant de fermer.');return false}}
const all=()=>state.plan.flatMap(w=>w.sessions);const num=v=>Number(v)||0;const done=s=>state.logs.some(l=>l.sessionId===s.id);const pace=(m,k)=>{if(!num(m)||!num(k))return '—';let x=Math.round(m*60/k);return `${Math.floor(x/60)}:${String(x%60).padStart(2,'0')}/km`};const metric=(label,value)=>`<div class="card"><small>${esc(label)}</small><div class="metric">${esc(value)}</div></div>`;
function session(s){return `<div class="line"><div class="row"><small>${fmt(s.date)} · ${esc(s.sport)}</small><span class="pill">${done(s)?'✓ Réalisée':s.optional?'Facultatif':'Prévue'}</span></div><h3>${esc(s.title)} ${s.minutes?'· '+s.minutes+' min':''}</h3><p class="muted">${esc(s.detail)}</p>${s.sport==='Course'&&!state.medical?'<small>Reprise non autorisée : ne pas courir.</small>':`<button class="secondary" onclick="logFor('${esc(s.id)}')">${done(s)?'Voir / saisir':'Enregistrer'}</button>`}</div>`}
function home(){let week=currentWeek();let w=state.plan.find(x=>x.week===week)||state.plan[0], ss=w.sessions.filter(s=>!s.optional), count=ss.filter(done).length, next=all().find(s=>s.date>=today()&&!done(s)&&!s.optional&&!state.skipped.includes(s.id)), days=Math.max(0,Math.round((new Date('2027-03-21T12:00:00')-new Date(today()+'T12:00:00'))/86400000));return `<h1>Ton objectif, chaque jour.</h1><div class="card hero"><small>SEMI-MARATHON · 21 MARS 2027</small><div class="metric">${esc(state.settings.target)} h</div><p>${days} jours restants · ${esc(state.settings.pace)}/km</p><small>Chrono cible à valider par les tests.</small></div>${!state.medical?'<div class="card warn"><h3>Reprise en attente</h3><p>Course uniquement après autorisation médicale concernant les engourdissements. Vélo facile si bien toléré.</p><button class="secondary" onclick="go(\'coach\')">Statut de reprise</button></div>':''}<div class="grid">${metric('Semaine',week+' / 16')}${metric('Séances réalisées',count+' / '+ss.length)}</div><div class="card"><h2>${esc(w.phase)}</h2><div class="bar"><i style="width:${ss.length?count/ss.length*100:0}%"></i></div><p>Objectif : régularité, récupération et absence de symptômes.</p></div>${next?`<div class="card"><h2>Prochaine séance prévue</h2>${session(next)}</div>`:''}<button onclick="go('log')">+ Ajouter une séance</button>`}
function planning(){let w=state.plan.find(x=>x.week===week)||state.plan[0];return `<h1>Planning</h1><div class="card"><div class="row"><button class="secondary" onclick="shift(-1)" ${week<=0?'disabled':''}>‹</button><div style="text-align:center"><h2>Semaine ${week}</h2><small>${fmt(weekStart(week))} – ${fmt(weekEnd(week))}</small></div><button class="secondary" onclick="shift(1)" ${week>=16?'disabled':''}>›</button></div><label>Accès direct</label><select onchange="week=Number(this.value);render()">${state.plan.map(w=>`<option value="${w.week}" ${w.week===week?'selected':''}>S${w.week} · ${esc(w.phase)}</option>`).join('')}</select><p class="muted">Les séances et volumes sont conditionnels. Samedi repos; aucun rattrapage forcé.</p>${w.sessions.map(session).join('')}</div>`}
const fields=[['duration','Durée (min)','number'],['distance','Distance (km)','number'],['avgHR','FC moyenne (bpm)','number'],['maxHR','FC maximale observée','number'],['power','Puissance moyenne vélo (W)','number'],['cadence','Cadence (rpm ou pas/min)','number'],['vo2','VO₂ max Garmin','number'],['rpe','RPE (1–10)','number'],['fatigue','Fatigue (0–10)','number'],['sleep','Sommeil (h)','number'],['restHR','FC au repos (bpm)','number'],['weight','Poids (kg)','number'],['elevation','Dénivelé positif (m)','number'],['soreness','Courbatures (0–10)','number'],['hrv','VFC nocturne (ms)','number'],['pain','Douleur (0–10)','number'],['carbs','Glucides pendant séance (g)','number'],['water','Eau pendant séance (ml)','number']];
function log(){let l=editing?state.logs.find(x=>x.id===editing):null,s=all().find(x=>x.id===planned);let v=l||{date:s?.date||today(),sport:s?.sport||'Course',sessionId:s?.id||'',duration:s?.minutes||'',title:s?.title||''};return `<h1>Carnet</h1><form id="entry" class="card"><h2>${l?'Modifier la séance':'Nouvelle donnée'}</h2><label>Date</label><input name="date" type="date" required value="${esc(v.date)}"><label>Activité</label><select name="sport">${['Course','Vélo','Musculation','Récupération'].map(x=>`<option ${x===v.sport?'selected':''}>${x}</option>`).join('')}</select><label>Séance prévue associée</label><select name="sessionId"><option value="">Aucune / libre</option>${all().map(s=>`<option value="${esc(s.id)}" ${s.id===v.sessionId?'selected':''}>${fmt(s.date)} · ${esc(s.title)}</option>`).join('')}</select><label>Intitulé</label><input name="title" value="${esc(v.title)}"><div class="grid">${fields.map(([k,n,t])=>`<div><label>${n}</label><input name="${k}" type="${t}" step="any" min="${k==='rpe'?1:0}" ${['rpe','fatigue','soreness','pain'].includes(k)?'max="10"':k==='sleep'?'max="24"':''} value="${esc(v[k])}" inputmode="decimal"></div>`).join('')}</div><label>Douleur ou engourdissement ?</label><select name="symptoms"><option ${v.symptoms==='Non'?'selected':''}>Non</option><option ${v.symptoms==='Oui'?'selected':''}>Oui</option></select><label>Détail des intervalles / charges / symptômes</label><textarea name="notes" placeholder="Allures par répétition, récupérations, charges, sensations…">${esc(v.notes)}</textarea><p id="symWarn" class="muted"></p><div class="actions"><button type="submit">Sauvegarder</button>${l?'<button type="button" class="secondary" onclick="editing=null;planned=null;render()">Annuler</button>':''}</div></form><h2>Historique</h2>${state.logs.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(l=>`<div class="card"><small>${fmt(l.date)} · ${esc(l.sport)}</small><h3>${esc(l.title||l.sport)}</h3><p>${esc(l.duration||'—')} min · ${esc(l.distance||'—')} km · ${pace(l.duration,l.distance)} · RPE ${esc(l.rpe||'—')}</p><p>${esc(l.notes)}</p><div class="actions"><button class="secondary" onclick="edit('${esc(l.id)}')">Modifier</button><button class="danger" onclick="removeLog('${esc(l.id)}')">Supprimer</button></div></div>`).join('')||'<p class="empty">Aucune donnée enregistrée.</p>'}`}
function progress(){let runs=state.logs.filter(l=>l.sport==='Course'), weekly=state.plan.map(w=>({w:w.week,km:runs.filter(l=>l.date>=weekStart(w.week)&&l.date<=weekEnd(w.week)).reduce((a,l)=>a+num(l.distance),0)})), max=Math.max(1,...weekly.map(x=>x.km)), tests=runs.filter(l=>num(l.distance)>0&&num(l.duration)>0);return `<h1>Progression</h1><div class="grid">${metric('Distance cumulée',runs.reduce((a,l)=>a+num(l.distance),0).toFixed(1)+' km')}${metric('Séances course',runs.length)}${metric('Dernière VO₂ max',state.logs.slice().sort((a,b)=>b.date.localeCompare(a.date)).find(l=>num(l.vo2))?.vo2||'—')}${metric('Dernière FC repos',state.logs.slice().sort((a,b)=>b.date.localeCompare(a.date)).find(l=>num(l.restHR))?.restHR||'—')}</div><div class="card"><h2>Volume réel par semaine</h2>${weekly.map(x=>`<div class="row"><small>S${x.w}</small><div class="bar" style="flex:1"><i style="width:${x.km/max*100}%"></i></div><small>${x.km.toFixed(1)} km</small></div>`).join('')}</div><div class="card"><h2>Allures de référence</h2>${Object.entries(state.settings).map(([k,v])=>`<div class="row line"><small>${esc(({target:'Chrono cible',pace:'Allure semi cible',ef:'EF',threshold:'Seuil',vma:'VMA'})[k]||k)}</small><b>${esc(v)}</b></div>`).join('')}<button class="secondary" onclick="go('coach')">Modifier les repères</button></div><div class="card"><h2>Estimer le potentiel semi</h2><label>Distance du test</label><select id="td"><option>5</option><option>10</option></select><label>Chrono (minutes décimales, ex. 23,5)</label><input id="tt" type="number" step="any" min="1" placeholder="23.5"><button style="margin-top:10px" onclick="estimate()">Calculer</button><p id="prediction"></p><small>Modèle de Riegel, non garanti; dépend de l'endurance.</small></div><div class="card"><h2>Dernières courses</h2>${tests.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,12).map(l=>`<div class="line">${fmt(l.date)} · ${esc(l.distance)} km · ${pace(l.duration,l.distance)}<br><small>FC ${esc(l.avgHR||'—')} · RPE ${esc(l.rpe||'—')}</small></div>`).join('')||'<small>Les données apparaîtront après tes séances.</small>'}</div>`}
function coach(){return `<h1>Espace coach</h1><div class="card warn"><h2>Autorisation médicale</h2><label><input id="med" type="checkbox" ${state.medical?'checked':''} onchange="state.medical=this.checked;save();render()"> Reprise autorisée par un professionnel de santé</label><p>En cas de retour des engourdissements : arrêter et faire réévaluer. Ne pas cocher pour un simple changement de chaussures.</p></div><div class="card"><h2>Repères individualisés</h2><form id="settings">${Object.entries(state.settings).map(([k,v])=>`<label>${esc(({target:'Chrono cible',pace:'Allure semi (min/km)',ef:'Allure EF / FC',threshold:'Allure seuil / FC',vma:'VMA / allure'})[k]||k)}</label><input name="${esc(k)}" value="${esc(v)}">`).join('')}<button style="margin-top:12px">Enregistrer</button></form></div><div class="card"><h2>Transmettre ton bilan</h2><p>Exporte les séances, le planning et les repères. Envoie le fichier JSON dans notre conversation pour obtenir un ajustement.</p><div class="actions"><button onclick="download('hybrid-run-bilan.json',JSON.stringify(state,null,2))">Exporter JSON</button><button class="secondary" onclick="copyReport()">Copier le bilan</button></div><p id="copyStatus"></p><details><summary>Voir le bilan texte</summary><textarea readonly id="report">${esc(report())}</textarea></details></div><div class="card"><h2>Importer un planning corrigé</h2><p>Importe un JSON contenant <code>plan</code> (16 semaines, séances avec identifiants stables) et éventuellement <code>settings</code> et <code>version</code>. Ton historique est conservé.</p><input id="importPlan" type="file" accept=".json,application/json"><button class="secondary" style="margin-top:10px" onclick="importFile(false)">Importer le planning</button><details><summary>Restaurer une sauvegarde complète</summary><p>Remplace planning et historique par une sauvegarde exportée.</p><input id="restore" type="file" accept=".json,application/json"><button class="danger" onclick="importFile(true)">Restaurer</button></details></div><div class="card"><h2>Installation & confidentialité</h2><p>Safari → Partager → Sur l’écran d’accueil. Les données restent dans le stockage local de cet appareil, sans synchronisation ni connexion automatique à ChatGPT ou Garmin. Exporte régulièrement une sauvegarde.</p><p>Programme ${esc(state.version)} · application 1.0.</p></div>`}
function report(){return `Bilan Hybrid Run — ${today()}\nProgramme ${state.version} · autorisation médicale : ${state.medical?'oui':'non'}\nRepères : ${JSON.stringify(state.settings)}\nSéances enregistrées :\n${state.logs.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(l=>`${l.date} | ${l.sport} | ${l.title||''} | ${fields.map(([k,n])=>l[k]!==''&&l[k]!=null?`${n}: ${l[k]}`:'').filter(Boolean).join(' | ')} | symptômes: ${l.symptoms} | ${l.notes||''}`).join('\n')}\nMerci d’analyser les résultats et de proposer les prochaines semaines au format JSON compatible, en conservant les identifiants des séances déjà réalisées.`}
function download(name,content){let u=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}async function copyReport(){try{await navigator.clipboard.writeText(report());$('copyStatus').textContent='Bilan copié.'}catch{$('copyStatus').textContent='Copie manuelle : ouvre le bilan texte ci-dessous.'}}
function validPlan(p){return Array.isArray(p)&&p.length===17&&p.every((w,i)=>w.week===i&&typeof w.phase==='string'&&Array.isArray(w.sessions)&&w.sessions.every(s=>typeof s.id==='string'&&/^[a-zA-Z0-9_-]+$/.test(s.id)&&typeof s.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s.date)&&typeof s.title==='string'&&typeof s.detail==='string'&&['Course','Vélo','Musculation','Récupération'].includes(s.sport)&&Number.isFinite(s.minutes)&&s.minutes>=0))&&new Set(p.flatMap(w=>w.sessions.map(s=>s.id))).size===p.flatMap(w=>w.sessions).length}
async function importFile(full){let f=$(full?'restore':'importPlan').files[0];if(!f)return alert('Sélectionne un fichier JSON.');try{if(f.size>5000000)throw Error('Fichier trop volumineux.');let x=JSON.parse(await f.text());x.plan=normalisePlan(x.plan,full);if(!validPlan(x.plan))throw Error('Planning invalide : semaine 0 + 16 semaines (ou ancien format 16 semaines).');if(full&&(!Array.isArray(x.logs)||!x.logs.every(validLog)||new Set(x.logs.map(l=>l.id)).size!==x.logs.length))throw Error('Historique invalide.');if(!full){let incoming=x.plan.flatMap(w=>w.sessions);for(let l of state.logs){if(l.sessionId){let old=all().find(s=>s.id===l.sessionId),next=incoming.find(s=>s.id===l.sessionId);if(old&&(!next||['date','sport','title','minutes','detail'].some(k=>old[k]!==next[k])))throw Error('Import refusé : une séance déjà enregistrée a été modifiée ou supprimée.')}}}if(!confirm(full?'Remplacer les données actuelles ?':'Remplacer le planning en conservant le carnet ?'))return;let before=JSON.stringify(state);let next=structuredClone(state);next.plan=x.plan;if(x.settings&&typeof x.settings==='object')for(let k of Object.keys(next.settings))if(typeof x.settings[k]==='string')next.settings[k]=x.settings[k];if(typeof x.version==='string')next.version=x.version;if(full){next.logs=x.logs;next.shoes=Array.isArray(x.shoes)?x.shoes.filter(s=>s&&typeof s.id==='string'&&typeof s.name==='string'):[];next.light=!!x.light;next.medical=false;next.daily=Array.isArray(x.daily)?x.daily.filter(validDaily):[];next.skipped=Array.isArray(x.skipped)?x.skipped.filter(v=>typeof v==='string'):[];}localStorage.setItem(KEY+'-undo',before);localStorage.setItem(KEY,JSON.stringify(next));state=next;render();alert('Import terminé.')}catch(e){alert(e.message)}}
function estimate(){let t=num($('tt').value),d=num($('td').value);if(t<=0)return;let sec=Math.round(t*60*(21.0975/d)**1.06);$('prediction').textContent=`${Math.floor(sec/3600)} h ${Math.floor(sec%3600/60)} min ${sec%60} s — estimation théorique.`}
function go(t){tab=t;render();window.scrollTo(0,0)}function shift(n){week=Math.max(0,Math.min(16,week+n));render()}function logFor(id){let l=state.logs.find(x=>x.sessionId===id);editing=l?.id||null;planned=id;go('log')}function edit(id){editing=id;planned=null;go('log')}function removeLog(id){if(confirm('Supprimer cette séance ?')){state.logs=state.logs.filter(x=>x.id!==id);editing=null;save();render()}}
function render(){$('app').innerHTML=({home,planning,log,progress,coach})[tab]();$('nav').innerHTML=[['home','⌂','Accueil'],['planning','▦','Planning'],['log','＋','Carnet'],['progress','↗','Progression'],['coach','◎','Coach']].map(([t,i,n])=>`<button class="${tab===t?'active':''}" onclick="go('${t}')"><b>${i}</b>${n}</button>`).join('');if($('entry')){$('entry').symptoms.onchange=()=>{$('symWarn').textContent=$('entry').symptoms.value==='Oui'?'Arrêter l’activité concernée et demander une réévaluation médicale.':''};$('entry').onsubmit=e=>{e.preventDefault();let l=Object.fromEntries(new FormData(e.target));l.id=editing||('l'+Date.now()+Math.random().toString(36).slice(2,8));if(l.symptoms==='Oui'){state.medical=false;alert('Interromps l’activité concernée et fais réévaluer les symptômes.')}if(l.sessionId){let p=all().find(s=>s.id===l.sessionId);if(!p||p.sport!==l.sport){alert('Séance associée incompatible avec le sport choisi.');return}} if(l.avgHR&&l.maxHR&&num(l.avgHR)>num(l.maxHR)){alert('FC moyenne supérieure à la FC maximale : vérifie les données.');return}state.logs=state.logs.filter(x=>x.id!==l.id);state.logs.push(l);editing=null;planned=null;save();render()}}if($('settings'))$('settings').onsubmit=e=>{e.preventDefault();state.settings=Object.fromEntries(new FormData(e.target));save();render()}}

// Version 2 — journal quotidien, plan ajustable, analyses, minuteur et sauvegardes.
const currentWeek=()=>Math.max(0,Math.min(16,Math.floor((Date.UTC(...today().split('-').map((v,i)=>Number(v)-(i===1?1:0)))-Date.UTC(2026,10,30))/604800000)+1));
const dateOK=d=>typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)&&!isNaN(Date.parse(d))&&new Date(d+'T12:00:00Z').toISOString().slice(0,10)===d;
const validLog=l=>l&&typeof l.id==='string'&&/^[a-zA-Z0-9_-]+$/.test(l.id)&&dateOK(l.date)&&['Course','Vélo','Musculation','Récupération'].includes(l.sport);
const validDaily=l=>l&&dateOK(l.date)&&['sleep','restHR','weight','fatigue','soreness','hrv'].every(k=>l[k]==null||l[k]===''||Number.isFinite(Number(l[k])));
state.daily=Array.isArray(state.daily)?state.daily.filter(validDaily):[];state.skipped=Array.isArray(state.skipped)?state.skipped:[];
const oldValidPlan=validPlan;validPlan=p=>oldValidPlan(p)&&p.every(w=>w.sessions.every(s=>dateOK(s.date)&&s.date>=weekStart(w.week)&&s.date<=weekEnd(w.week)&&s.minutes<=300));
const oldSession=session;session=s=>oldSession(s)+`<div class="actions" style="margin:8px 0"><button class="secondary" onclick="editPlan('${esc(s.id)}')" ${done(s)?'disabled':''}>Adapter</button><button class="secondary" onclick="skipSession('${esc(s.id)}')" ${done(s)?'disabled':''}>${state.skipped.includes(s.id)?'↶ Rétablir':'Passer'}</button></div>${state.skipped.includes(s.id)?'<small>Session passée — pas de rattrapage automatique.</small>':''}`;
function skipSession(id){state.skipped=state.skipped.includes(id)?state.skipped.filter(x=>x!==id):[...state.skipped,id];save();render()}
function editPlan(id){let s=all().find(s=>s.id===id);if(!s||done(s))return;let d=document.createElement('dialog');d.innerHTML=`<form method="dialog" id="planEdit"><h2>Adapter la séance</h2><label>Titre</label><input name="title" required value="${esc(s.title)}"><label>Date (dans la même semaine)</label><input name="date" type="date" required value="${esc(s.date)}"><label>Durée (min)</label><input name="minutes" type="number" min="0" max="300" required value="${s.minutes}"><label>Consignes</label><textarea name="detail" required>${esc(s.detail)}</textarea><div class="actions"><button value="save">Enregistrer</button><button type="button" class="secondary" id="cancelEdit">Annuler</button></div></form>`;document.body.append(d);d.querySelector('#cancelEdit').onclick=()=>d.close();d.querySelector('form').onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target)),w=state.plan.find(w=>w.sessions.includes(s));if(v.date<weekStart(w.week)||v.date>weekEnd(w.week)){alert('Choisis une date dans cette semaine.');return}Object.assign(s,v,{minutes:Number(v.minutes)});w.sessions.sort((a,b)=>a.date.localeCompare(b.date));save();d.close();render()};d.onclose=()=>d.remove();d.showModal()}
function dailyCard(){let v=state.daily.find(l=>l.date===today())||{};return `<div class="card"><h2>Check-in quotidien</h2><form id="daily"><label>Date</label><input name="date" type="date" value="${today()}" required><div class="grid">${[['sleep','Sommeil (h)',24],['restHR','FC repos',220],['weight','Poids (kg)',300],['fatigue','Fatigue /10',10],['soreness','Courbatures /10',10],['hrv','VFC (ms)',500]].map(([k,n,m])=>`<div><label>${n}</label><input name="${k}" type="number" min="0" max="${m}" step="any" value="${esc(v[k])}"></div>`).join('')}</div><label>Notes / symptômes</label><textarea name="notes">${esc(v.notes)}</textarea><button style="margin-top:10px">Enregistrer le check-in</button></form></div>`}
function weekStats(w=currentWeek()){let from=weekStart(w),to=weekEnd(w),logs=state.logs.filter(l=>l.date>=from&&l.date<=to),runs=logs.filter(l=>l.sport==='Course');return {logs,runs,km:runs.reduce((a,l)=>a+num(l.distance),0),minutes:runs.reduce((a,l)=>a+num(l.duration),0),load:logs.reduce((a,l)=>a+(num(l.rpe)&&num(l.duration)?num(l.rpe)*num(l.duration):0),0)}}
function recovery(){let a=state.daily.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3),sleep=a.filter(x=>num(x.sleep)>0),avg=sleep.length?sleep.reduce((v,l)=>v+num(l.sleep),0)/sleep.length:null;if(!state.medical)return 'Course suspendue : autorisation médicale requise.';if(a.some(x=>num(x.fatigue)>=7||num(x.soreness)>=7)||avg!==null&&avg<7)return 'Récupération à surveiller : pas de hausse de charge, réduire ou remplacer l’effort intense.';return a.length?'Pas de signal dans les données saisies. Ce n’est pas une validation médicale.':'Renseigne ton sommeil et ta fatigue pour suivre la récupération.'}
const origHome=home;home=()=>{let w=currentWeek(),x=weekStats(w);return origHome()+`<div class="grid">${metric('Course cette semaine',x.km.toFixed(1)+' km')}${metric('Charge sRPE renseignée',x.load+' UA')}</div><div class="card warn"><h2>Récupération</h2><p>${esc(recovery())}</p></div>${dailyCard()}`};
const origLog=log;log=()=>origLog()+`<div class="card"><h2>Conseil de saisie</h2><p>Durée en minutes décimales (23 min 30 = 23,5). Pour un test, utilise une entrée distincte correspondant uniquement au bloc chronométré et indique « test 5 km » ou « test 10 km » dans le titre. Ne double pas la durée dans le volume : saisis seulement le reste de la séance dans une autre entrée.</p></div>`;
const origProgress=progress;progress=()=>{let tests=state.logs.filter(l=>l.sport==='Course'&&num(l.duration)>0&&/test|chrono/i.test(l.title||''));let best=d=>tests.filter(l=>Math.abs(num(l.distance)-d)<0.005).sort((a,b)=>num(a.duration)-num(b.duration))[0];let chrono=l=>{if(!l)return '—';let s=Math.round(num(l.duration)*60);return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`};return origProgress()+`<div class="grid">${metric('Meilleur test 5 km',chrono(best(5)))}${metric('Meilleur test 10 km',chrono(best(10)))}</div><div class="card"><h2>Charge hebdomadaire réelle</h2><small>Durée × RPE, unités arbitraires ; seules les séances renseignées sont comptées. Pas de seuil médical automatique.</small>${state.plan.map(w=>{let x=weekStats(w.week);return `<div class="row line"><small>S${w.week}</small><span>${x.minutes.toFixed(0)} min course</span><b>${x.load.toFixed(0)} UA</b></div>`}).join('')}</div><div class="card"><h2>Récupération récente</h2>${state.daily.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,14).map(l=>`<div class="line"><b>${fmt(l.date)}</b><p>Sommeil ${esc(l.sleep||'—')} h · FC repos ${esc(l.restHR||'—')} · Fatigue ${esc(l.fatigue||'—')}/10</p></div>`).join('')||'<small>Aucun check-in.</small>'}</div>`};
const origCoach=coach;coach=()=>origCoach().replace('application 1.0','application 2.0')+`<div class="card"><h2>Outils de préparation</h2><div class="actions"><button onclick="go('timer')">Minuteur de fractionné</button><button class="secondary" onclick="exportCSV()">Exporter CSV</button></div><p>Le CSV est destiné à Excel. Le JSON conserve toutes les données et le planning.</p><button class="secondary" onclick="undoImport()">Annuler le dernier import</button><p><small>Les données sont locales et ne sont pas synchronisées automatiquement. Une sauvegarde est indispensable avant de changer de téléphone ou d’adresse du site.</small></p></div>`;
function exportCSV(){let keys=['date','sport','title',...fields.map(f=>f[0]),'symptoms','notes'];let cell=v=>'"'+String(v??'').replace(/^[=+\-@\t\r]/,"'$&").replace(/"/g,'""')+'"';download('hybrid-run-seances.csv','\ufeff'+[keys.join(';'),...state.logs.map(l=>keys.map(k=>cell(l[k])).join(';'))].join('\r\n'))}
function undoImport(){try{let raw=localStorage.getItem(KEY+'-undo');if(!raw)return alert('Aucun import à annuler.');if(!confirm('Restaurer les données avant le dernier import ? Les modifications effectuées depuis seront perdues.'))return;let x=JSON.parse(raw);x.plan=normalisePlan(x.plan,true);if(!validPlan(x.plan)||!Array.isArray(x.logs))throw Error('Sauvegarde invalide');localStorage.setItem(KEY,JSON.stringify(x));state=x;localStorage.removeItem(KEY+'-undo');render()}catch(e){alert(e.message)}}
const oldReport=report;report=()=>oldReport()+ '\nCheck-ins quotidiens :\n'+JSON.stringify(state.daily,null,2)+'\nSéances passées : '+JSON.stringify(state.skipped)+'\nPour modifier le planning, fournir un JSON {plan, settings, version} en gardant les séances enregistrées intactes. Ne pas accélérer en cas de fatigue ou de symptômes.';
let timerState=null,tick=null;
function timer(){return `<h1>Minuteur</h1><div class="card warn"><p>${state.medical?'Fractionné seulement après adaptation suffisante et selon le programme.':'Course non autorisée. Ne pas utiliser ce minuteur pour une séance de course.'}</p></div><div class="card"><h2>Configurer les intervalles</h2><div class="grid">${[['tw','Échauffement (min)',15],['te','Effort (s)',60],['tr','Récupération (s)',90],['tn','Répétitions',6],['tc','Retour au calme (min)',10]].map(([id,n,v])=>`<div><label>${n}</label><input id="${id}" type="number" min="1" max="3600" step="1" value="${v}"></div>`).join('')}</div><div class="actions" style="margin-top:12px"><button onclick="startTimer()" ${state.medical?'':'disabled'}>Démarrer</button><button class="secondary" onclick="pauseTimer()">Pause / reprise</button><button class="danger" onclick="stopTimer()">Arrêter</button></div><div id="timerDisplay" class="metric" style="font-size:48px;text-align:center">00:00</div><p id="timerPhase" style="text-align:center">Prêt</p><small>Garde l’application ouverte. Sur iOS, le minuteur et les signaux peuvent être suspendus en arrière-plan. Utilise aussi ta montre.</small></div><button class="secondary" onclick="go('coach')">Retour coach</button>`}
function startTimer(){if(!state.medical)return;let v=['tw','te','tr','tn','tc'].map(k=>Number($(k).value));if(v.some(x=>!Number.isInteger(x)||x<=0)||v[0]>60||v[1]>1200||v[2]>1200||v[3]>40||v[4]>60)return alert('Vérifie les durées et le nombre de répétitions.');let [w,e,r,n,c]=v,blocks=[['Échauffement',w*60]];for(let i=0;i<n;i++){blocks.push([`Effort ${i+1}/${n}`,e]);if(i<n-1)blocks.push(['Récupération',r])}blocks.push(['Retour au calme',c*60]);stopTimer();timerState={blocks,i:0,end:Date.now()+blocks[0][1]*1000,paused:0};tick=setInterval(updateTimer,250);updateTimer()}
function updateTimer(){if(!timerState)return;let t=timerState;if(!t.paused){while(Date.now()>=t.end){t.i++;if(t.i>=t.blocks.length){stopTimer();if($('timerPhase'))$('timerPhase').textContent='Terminé';return}t.end+=t.blocks[t.i][1]*1000;try{navigator.vibrate?.(150)}catch{}}}let s=Math.max(0,Math.ceil((t.paused||t.end-Date.now())/1000));if($('timerDisplay'))$('timerDisplay').textContent=`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;if($('timerPhase'))$('timerPhase').textContent=t.blocks[t.i][0]+(t.paused?' · pause':'')}
function pauseTimer(){if(!timerState)return;let t=timerState;if(t.paused){t.end=Date.now()+t.paused;t.paused=0}else t.paused=Math.max(1,t.end-Date.now());updateTimer()}
function stopTimer(){clearInterval(tick);tick=null;timerState=null;if($('timerDisplay'))$('timerDisplay').textContent='00:00';if($('timerPhase'))$('timerPhase').textContent='Prêt'}
const origRender=render;render=()=>{if(tab==='timer'){$('app').innerHTML=timer();updateTimer();return}origRender();if($('daily'))$('daily').onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target));if(!validDaily(v))return alert('Données invalides');state.daily=state.daily.filter(l=>l.date!==v.date);state.daily.push(v);let ok=save();render();if(ok)v31Notice('Check-in enregistré.')};};
// V2.1 — bilan structuré pour le coach, distinct de la sauvegarde.
let coachWeek=currentWeek();
function buildCoachExport(w){
 const from=weekStart(w),to=weekEnd(w),asOf=today();
 const present=v=>v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v));
 const round=v=>Math.round(v*100)/100;
 const avg=(rows,k)=>{const a=rows.filter(x=>present(x[k]));return {value:a.length?round(a.reduce((s,x)=>s+Number(x[k]),0)/a.length):null,count:a.length}};
 const summarize=(start,end)=>{const logs=state.logs.filter(l=>l.date>=start&&l.date<=end),daily=state.daily.filter(l=>l.date>=start&&l.date<=end),runs=logs.filter(l=>l.sport==='Course');const sports={};for(const sport of ['Course','Vélo','Musculation','Récupération']){const a=logs.filter(l=>l.sport===sport),load=a.filter(l=>present(l.duration)&&present(l.rpe));sports[sport]={entries:a.length,duration_min:round(a.reduce((s,l)=>s+num(l.duration),0)),duration_count:a.filter(l=>present(l.duration)).length,load_srpe:load.length?round(load.reduce((s,l)=>s+num(l.duration)*num(l.rpe),0)):null,load_count:load.length}}return {from:start,to:end,by_sport:sports,running_km:round(runs.reduce((s,l)=>s+num(l.distance),0)),running_distance_count:runs.filter(l=>present(l.distance)).length,longest_running_entry_min:runs.some(l=>present(l.duration))?Math.max(...runs.filter(l=>present(l.duration)).map(l=>Number(l.duration))):null,daily_checkins:daily.length,recovery:Object.fromEntries(['sleep','restHR','weight','fatigue','soreness','hrv'].map(k=>[k,avg(daily,k)])),symptoms_entries:logs.filter(l=>l.symptoms==='Oui'||num(l.pain)>0).map(l=>({id:l.id,date:l.date,notes:l.notes,pain:l.pain,symptoms:l.symptoms}))}};
 const planned=state.plan.find(x=>x.week===w).sessions.map(s=>({...s,status:done(s)?'logged':state.skipped.includes(s.id)?'skipped':s.date>asOf?'future':'not_logged',linked_log_ids:state.logs.filter(l=>l.sessionId===s.id).map(l=>l.id)}));
 return {schema:'hybrid-run-coach-report/1',exported_at:new Date().toISOString(),application_version:'2.1',focus:{week:w,from,to,as_of:asOf,partial:asOf<to},instructions:'Analyser la semaine sélectionnée et son historique, comparer prévu/réalisé, distinguer données manquantes et zéros, évaluer récupération et progression, proposer les prochaines semaines. Ne pas traiter les tests contrôlés comme des chronos maximaux. Respecter les symptômes et le statut médical; aucune reprise sans autorisation. Retour attendu : JSON {plan, settings, version} avec les 16 semaines et les identifiants stables; ne pas modifier les séances déjà enregistrées.',units:Object.fromEntries(fields.map(([k,label])=>[k,label])),interpretation:{blank:'Non renseigné; ne pas imputer zéro',duration:'Minutes décimales; les entrées de test peuvent être séparées du reste de la séance',load:'Durée × RPE, seulement si les deux valeurs sont renseignées',recovery:'Moyennes des check-ins uniquement; les nombres de mesures sont fournis',status:'not_logged ne signifie pas nécessairement manqué',distance:'Sommes des valeurs renseignées uniquement'},summary:summarize(from,to),weekly_history:state.plan.filter(x=>x.week<=w).map(x=>({week:x.week,...summarize(weekStart(x.week),weekEnd(x.week))})),planned_vs_logged:planned,selected_logs:state.logs.filter(l=>l.date>=from&&l.date<=to),selected_daily:state.daily.filter(l=>l.date>=from&&l.date<=to),test_candidates:state.logs.filter(l=>l.sport==='Course'&&/test|chrono|5 km|10 km/i.test(l.title||'')),...structuredClone(state)};
}
function exportCoach(){const x=buildCoachExport(coachWeek);download(`Hybrid-Run-Bilan-S${String(coachWeek).padStart(2,'0')}-${x.focus.from}.json`,JSON.stringify(x,null,2))}
const coachV2=coach;coach=()=>coachV2().replace('application 2.0','application 2.1').replace('<h1>Espace coach</h1>',`<h1>Espace coach</h1><div class="card hero"><h2>Bilan hebdomadaire pour ChatGPT</h2><p>Un seul fichier : données brutes, historique, récupération, prévu/réalisé et planning complet.</p><label>Semaine à analyser</label><select onchange="coachWeek=Number(this.value);render()">${state.plan.map(w=>`<option value="${w.week}" ${w.week===coachWeek?'selected':''}>S${w.week} · ${fmt(weekStart(w.week))} – ${fmt(weekEnd(w.week))}</option>`).join('')}</select><p>${weekStats(coachWeek).logs.length} entrées enregistrées · ${state.daily.filter(l=>l.date>=weekStart(coachWeek)&&l.date<=weekEnd(coachWeek)).length} check-ins</p><button onclick="exportCoach()">Exporter mon bilan pour ChatGPT</button><p><small>Envoie ce fichier JSON dans la conversation. Il inclut tout l’historique, même si tu sélectionnes une seule semaine. Vérifie tes notes avant de le partager.</small></p></div>`).replace('>Exporter JSON<','>Sauvegarde complète JSON<');

// V3 — interface et données structurées, compatibilité V2.1.
state.shoes=Array.isArray(state.shoes)?state.shoes:[];
const iconPaths={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',planning:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4m8-4v4"/>',log:'<circle cx="12" cy="12" r="9"/><path d="M12 7v10M7 12h10"/>',progress:'<path d="M3 3v18h18M7 15l5-6 4 3 5-7"/>',coach:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>'};
const ico=k=>`<svg class="navicon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${iconPaths[k]}</svg>`;
const v3session=session;session=s=>v3session(s).replace('class="line"','class="session line"').replace('✓ Réalisée', 'Réalisée').replace(s.optional?'Facultatif':'Prévue',state.skipped.includes(s.id)&&!done(s)?'Ignorée':s.optional?'Facultatif':s.date<today()?'À renseigner':'Prévue');
