const opt=(values,v)=>values.map(x=>`<option ${x===v?'selected':''}>${esc(x)}</option>`).join('');
let draft=null,historyFilter='Tous';
function field(k,v){let f=fields.find(x=>x[0]===k);return `<div><label>${esc(f[1])}</label><input name="${k}" type="number" inputmode="decimal" step="any" min="${k==='rpe'?1:0}" ${['rpe','fatigue','soreness','pain'].includes(k)?'max="10"':''} value="${esc(v[k])}"></div>`}
function structuredRows(rows,kind){return (rows||[]).map(r=>`<div class="repeatrow">${(kind==='laps'?[['duration','Durée (s)'],['distance','Distance (m)'],['hr','FC moy.'],['power','Watts']]:[['exercise','Exercice'],['reps','Répétitions'],['kg','Charge kg'],['rir','RIR']]).map(([k,n])=>`<div><label>${n}</label><input data-key="${k}" ${k==='exercise'?'type="text"':'type="number" min="0" step="any"'} value="${esc(r[k])}"></div>`).join('')}<button type="button" class="secondary" onclick="this.parentElement.remove()">Retirer</button></div>`).join('')}
function readRows(id){return Array.from($(id)?.querySelectorAll('.repeatrow')||[]).map(r=>Object.fromEntries(Array.from(r.querySelectorAll('input')).map(x=>[x.dataset.key,x.value]))).filter(r=>Object.values(r).some(v=>v!==''))}
function collectDraft(){let f=$('entry');if(!f)return {};let v=Object.fromEntries(new FormData(f));v.duration=(num(v.hours)*3600+num(v.minutes)*60+num(v.seconds))/60||'';v.laps=readRows('laps');v.sets=readRows('sets');return v}
