function importActivity(){let f=$('activityFile').files[0];if(!f)return alert('Choisis un fichier TCX ou GPX.');if(f.size>15000000)return alert('Fichier trop volumineux.');f.text().then(txt=>{let x=new DOMParser().parseFromString(txt,'application/xml');if(x.querySelector('parsererror'))throw Error('XML invalide');let nodes=(e,n)=>Array.from(e.getElementsByTagNameNS('*',n)), val=(e,n)=>nodes(e,n)[0]?.textContent||'', isTCX=nodes(x,'Activity').length>0;let v={};v.sessionId='';v.testKind='Aucun';v.testSeconds='';v.laps=[];v.sets=[];v.title=f.name.replace(/\.[^.]+$/,'');v.sport='Course';if(isTCX){let activities=nodes(x,'Activity');if(activities.length!==1)throw Error('Un seul entraînement par fichier est accepté.');let a=activities[0],sport=a.getAttribute('Sport');if(sport==='Biking')v.sport='Vélo';else if(sport!=='Running')throw Error('Activité non prise en charge.');let laps=nodes(a,'Lap');let sum=n=>laps.reduce((s,l)=>s+num(val(l,n)),0);v.duration=sum('TotalTimeSeconds')/60||'';v.distance=sum('DistanceMeters')/1000||'';v.date=(val(a,'Id')||laps[0]?.getAttribute('StartTime')||today()).slice(0,10);v.laps=laps.map(l=>({duration:val(l,'TotalTimeSeconds'),distance:val(l,'DistanceMeters'),hr:val(nodes(l,'AverageHeartRateBpm')[0]||l,'Value')}));let hr=laps.map(l=>({h:num(val(nodes(l,'AverageHeartRateBpm')[0]||x.createElement('none'),'Value')),t:num(val(l,'TotalTimeSeconds'))})).filter(l=>l.h>0&&l.t>0);v.avgHR=hr.length?Math.round(hr.reduce((s,l)=>s+l.h*l.t,0)/hr.reduce((s,l)=>s+l.t,0)):'';let max=laps.map(l=>num(val(nodes(l,'MaximumHeartRateBpm')[0]||x.createElement('none'),'Value')));v.maxHR=Math.max(0,...max)||'';}else{let tracks=nodes(x,'trk');if(tracks.length!==1)throw Error('Un seul parcours GPX est accepté.');let segments=nodes(tracks[0],'trkseg'),dist=0,up=0,duration=0,first='';for(let seg of segments){let points=nodes(seg,'trkpt');for(let i=0;i<points.length;i++){let p=points[i];if(!first)first=val(p,'time');if(i){let a=points[i-1], rad=Math.PI/180,lat1=Number(a.getAttribute('lat'))*rad,lat2=Number(p.getAttribute('lat'))*rad,dl=(Number(p.getAttribute('lon'))-Number(a.getAttribute('lon')))*rad,h=Math.sin((lat2-lat1)/2)**2+Math.cos(lat1)*Math.cos(lat2)*Math.sin(dl/2)**2;dist+=6371*2*Math.asin(Math.sqrt(Math.min(1,h)));let e1=val(a,'ele'),e2=val(p,'ele');if(e1!==''&&e2!=='')up+=Math.max(0,Number(e2)-Number(e1));}}if(points.length>1){let a=Date.parse(val(points[0],'time')),b=Date.parse(val(points.at(-1),'time'));if(Number.isFinite(a)&&Number.isFinite(b)&&b>a)duration+=(b-a)/60000}}v.distance=dist.toFixed(3);v.duration=duration||'';v.elevation=up?Math.round(up):'';v.date=first.slice(0,10)||today();v.avgHR='';v.maxHR='';v.notes='GPX : distance estimée GPS, durée entre points horodatés. Vérifier le sport et les valeurs.'}if(!dateOK(v.date))v.date=today();v.rpe='';v.symptoms='Non renseigné';v.source=isTCX?'TCX':'GPX';draft=v;editing=null;planned=null;render();window.scrollTo(0,0)}).catch(e=>alert(e.message))}
