function graph(title,rows,key,unit){let a=rows.filter(r=>r[key]!==''&&r[key]!=null&&Number.isFinite(Number(r[key]))).sort((a,b)=>a.date.localeCompare(b.date));if(!a.length)return `<div class="card"><h2>${title}</h2><p class="muted">En attente de mesures.</p></div>`;let vals=a.map(r=>Number(r[key])),lo=Math.min(...vals),hi=Math.max(...vals),range=hi-lo||1,pts=a.map((r,i)=>[18+i*284/Math.max(1,a.length-1),105-(Number(r[key])-lo)/range*80]);return `<div class="card"><div class="row"><h2>${title}</h2><b>${esc(vals.at(-1).toFixed(1))} ${unit}</b></div><svg class="chart" viewBox="0 0 320 130" role="img" aria-label="${title}"><path d="M18 105H302M18 65H302M18 25H302" stroke="var(--line)" fill="none"/><polyline points="${pts.map(p=>p.join(',')).join(' ')}" stroke="var(--accent)" stroke-width="2.5" fill="none"/>${pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="var(--accent)"><title>${esc(a[i].date)} : ${vals[i]} ${unit}</title></circle>`).join('')}</svg><div class="row"><small>${fmt(a[0].date)}</small><small>${fmt(a.at(-1).date)}</small></div><details><summary>Valeurs (${a.length})</summary>${a.map(r=>`<div class="row line"><small>${fmt(r.date)}</small><b>${esc(r[key])} ${unit}</b></div>`).join('')}</details></div>`}
progress=()=>{let runs=state.logs.filter(l=>l.sport==='Course'),tests=actualTests(),best=d=>tests.filter(l=>l.testKind===d+' km maximal').sort((a,b)=>num(a.testSeconds)-num(b.testSeconds))[0],b5=best(5),b10=best(10),bestRef=b10||b5;let vals=state.plan.map(w=>{let a=weekStats(w.week),p=w.sessions.filter(s=>s.sport==='Course'&&!s.optional).reduce((v,s)=>v+s.minutes,0);return {w:w.week,p,a:a.minutes,km:a.km}}),max=Math.max(1,...vals.flatMap(x=>[x.a,x.p]));return `<div class="eyebrow">PERFORMANCE LAB</div><h1>Progression</h1><div class="grid">${metric('Record 5 km',b5?clock(num(b5.testSeconds)):'—')}${metric('Record 10 km',b10?clock(num(b10.testSeconds)):'—')}${metric('Distance cumulée',runs.reduce((s,l)=>s+num(l.distance),0).toFixed(1)+' km')}${metric('Potentiel semi indicatif',bestRef?clock(num(bestRef.testSeconds)*(21.0975/(b10?10:5))**1.06):'—')}</div><div class="card"><h2>Prévu / réalisé</h2><small>Minutes de course · objectif hors bonus et tests sans durée fixée</small>${vals.map(x=>`<div class="line"><div class="row"><b>S${x.w}</b><small>${x.a.toFixed(0)} / ${x.p} min · ${x.km.toFixed(1)} km</small></div><div class="bar"><i class="planned" style="width:${x.p/max*100}%"></i></div><div class="bar"><i style="width:${x.a/max*100}%"></i></div></div>`).join('')}</div>${graph('VO₂ max estimée',runs,'vo2','ml/kg/min')}${graph('Sommeil',state.daily,'sleep','h')}${graph('FC au repos',state.daily,'restHR','bpm')}${graph('VFC',state.daily,'hrv','ms')}${graph('Poids',state.daily,'weight','kg')}${graph('Tests 5 km maximaux',tests.filter(x=>x.testKind==='5 km maximal').map(x=>({...x,testMin:num(x.testSeconds)/60})),'testMin','min')}${graph('Tests 10 km maximaux',tests.filter(x=>x.testKind==='10 km maximal').map(x=>({...x,testMin:num(x.testSeconds)/60})),'testMin','min')}<div class="card"><h2>Repères intermédiaires</h2><p>5 km : environ 22–23 min · 10 km : 47–48 min · sortie longue : 90–110 min si assimilée. Aucun chrono n’est garanti.</p><p>AS21 : ${esc(state.settings.pace)}/km, à valider.</p></div>`};
