function calendarExport(){let safe=s=>String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/;/g,'\\;').replace(/,/g,'\\,');let stamp=new Date().toISOString().replace(/[-:]|\.\d+/g,'');let out=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Hybrid Run//Planning//FR'];for(let s of all().filter(s=>!state.skipped.includes(s.id)&&s.date>=today())){let next=new Date(s.date+'T12:00:00Z');next.setUTCDate(next.getUTCDate()+1);out.push('BEGIN:VEVENT',`UID:${s.id}@hybrid-run`,`DTSTAMP:${stamp}`,`DTSTART;VALUE=DATE:${s.date.replace(/-/g,'')}`,`DTEND;VALUE=DATE:${next.toISOString().slice(0,10).replace(/-/g,'')}`,`SUMMARY:${safe(s.title)}${s.optional?' (facultatif)':''}`,`DESCRIPTION:${safe(s.detail+(s.sport==='Course'?' — Uniquement après autorisation médicale et si bien toléré.':''))}`,'END:VEVENT')}out.push('END:VCALENDAR');download('hybrid-run-planning.ics',out.join('\r\n'))}
